// Rivertown Tool Library — deterministic lending logic (no DOM, no network).
// Type declarations for this file's domain.

type LoanStatus = 'Reserved' | 'Out' | 'Returned' | 'Overdue';
type Standing = 'Good' | 'Restricted';

type Tool = {
  id: string;
  name: string;
  category: string;
  condition: string;
  replacementCostPence: number;
  loanLengthDays: number;
  active: boolean;
};

type Member = {
  id: string;
  name: string;
  email: string;
  standing: Standing;
  joinDate: string;
};

type Loan = {
  id: string;
  toolId: string;
  memberId: string;
  status: LoanStatus;
  checkedOutAt: string | null;
  dueAt: string | null;
  returnedAt: string | null;
};

type DamageReport = {
  id: string;
  loanId: string;
  note: string;
  replacementChargePence: number;
  recordedAt: string;
};

type CatalogueRow = {
  id: string;
  name: string;
  category: string;
  condition: string;
  loanLengthDays: number;
  active: boolean;
  replacementCostPence: number;
  dueBackAt: string | null;
};

type OverdueRow = {
  loanId: string;
  toolId: string;
  memberId: string;
  dueAt: string;
  daysLate: number;
};

type CatalogueQuery = {
  searchText?: string;
  category?: string;
  availability?: 'available' | 'on-loan';
};

type Clock = {
  now: () => string;
};

type StoreShape = {
  tools: Tool[];
  members: Member[];
  loans: Loan[];
  damageReports: DamageReport[];
};

// Deterministic counter used to generate unique ids (no Math.random).
let idCounter = 0;

/**
 * Build a deterministic identifier from a prefix, seed and monotonic counter.
 * @param prefix - the prefix for the generated id.
 * @param seed - a deterministic seed string.
 * @returns a deterministic identifier string.
 */
function buildId(prefix: string, seed: string): string {
  idCounter += 1;
  let hash = 7;
  for (let i = 0; i < seed.length; i += 1) {
    hash = (hash * 31 + seed.charCodeAt(i)) % 1000000007;
  }
  return prefix + '-' + String(hash) + '-' + String(idCounter);
}

const store: StoreShape = { tools: [], members: [], loans: [], damageReports: [] };

/**
 * Seed deterministic catalogue and member data used by the persisted store.
 * @returns the seeded store document.
 */
function seedStore(): StoreShape {
  store.tools = [
    {
      id: 'tool-drill',
      name: 'Cordless Drill',
      category: 'Power Tools',
      condition: 'Good',
      replacementCostPence: 12000,
      loanLengthDays: 7,
      active: true,
    },
    {
      id: 'tool-ladder',
      name: 'Aluminium Ladder',
      category: 'Access',
      condition: 'Fair',
      replacementCostPence: 8000,
      loanLengthDays: 3,
      active: true,
    },
  ];
  store.members = [
    {
      id: 'member-ana',
      name: 'Ana Hughes',
      email: 'ana@rivertown.example',
      standing: 'Good',
      joinDate: '2020-01-01T00:00:00.000Z',
    },
    {
      id: 'member-ben',
      name: 'Ben Okafor',
      email: 'ben@rivertown.example',
      standing: 'Restricted',
      joinDate: '2021-05-01T00:00:00.000Z',
    },
  ];
  return store;
}

seedStore();

/**
 * Locate a tool by identifier.
 * @param toolId - the tool identifier.
 * @returns the matching tool or undefined.
 */
function findTool(toolId: string): Tool | undefined {
  for (let i = 0; i < store.tools.length; i += 1) {
    if (store.tools[i].id === toolId) {
      return store.tools[i];
    }
  }
  return undefined;
}

/**
 * Locate a member by identifier.
 * @param memberId - the member identifier.
 * @returns the matching member or undefined.
 */
function findMember(memberId: string): Member | undefined {
  for (let i = 0; i < store.members.length; i += 1) {
    if (store.members[i].id === memberId) {
      return store.members[i];
    }
  }
  return undefined;
}

/**
 * Locate a loan by identifier.
 * @param loanId - the loan identifier.
 * @returns the matching loan or undefined.
 */
function findLoan(loanId: string): Loan | undefined {
  for (let i = 0; i < store.loans.length; i += 1) {
    if (store.loans[i].id === loanId) {
      return store.loans[i];
    }
  }
  return undefined;
}

/**
 * Determine if a tool currently has an active (Reserved or Out) loan.
 * @param toolId - the tool identifier.
 * @returns true when the tool is on loan.
 */
function isToolOnLoan(toolId: string): boolean {
  for (let i = 0; i < store.loans.length; i += 1) {
    const loan = store.loans[i];
    if (loan.toolId === toolId && (loan.status === 'Reserved' || loan.status === 'Out' || loan.status === 'Overdue')) {
      return true;
    }
  }
  return false;
}

/**
 * Report whether a tool can currently be taken.
 * @param toolId - the tool identifier.
 * @returns true when the tool exists, is active and is not on loan.
 */
function isToolAvailable(toolId: string): boolean {
  const tool = findTool(toolId);
  if (tool === undefined || !tool.active) {
    return false;
  }
  return !isToolOnLoan(toolId);
}

/**
 * Parse an ISO timestamp into epoch milliseconds.
 * @param iso - the ISO timestamp string.
 * @returns epoch milliseconds, or NaN when unparseable.
 */
function parseTime(iso: string): number {
  return new Date(iso).getTime();
}

/**
 * Compute the date when a loan must be returned.
 * @param nowIso - the injected current time as an ISO string.
 * @param loanLengthDays - the loan length in days.
 * @returns the computed due-at ISO timestamp.
 */
function computeDueAt(nowIso: string, loanLengthDays: number): string {
  const base = parseTime(nowIso);
  return new Date(base + loanLengthDays * 86400000).toISOString();
}

/**
 * Derive the effective status of a loan given the injected clock.
 * @param loan - the loan under evaluation.
 * @param clock - the injected clock used for deterministic time.
 * @returns the effective LoanStatus.
 */
function deriveLoanStatus(loan: Loan, clock: Clock): LoanStatus {
  if (loan.status === 'Returned') {
    return 'Returned';
  }
  if (loan.dueAt !== null && parseTime(loan.dueAt) < parseTime(clock.now())) {
    return 'Overdue';
  }
  return loan.status === 'Overdue' ? 'Out' : loan.status;
}

/**
 * Count loans belonging to a member whose due date has passed.
 * @param memberId - the member identifier.
 * @param clock - the injected clock.
 * @returns the number of overdue loans for the member.
 */
function countMemberOverdue(memberId: string, clock: Clock): number {
  let count = 0;
  const now = parseTime(clock.now());
  for (let i = 0; i < store.loans.length; i += 1) {
    const loan = store.loans[i];
    if (
      loan.memberId === memberId &&
      loan.status !== 'Returned' &&
      loan.dueAt !== null &&
      parseTime(loan.dueAt) < now
    ) {
      count += 1;
    }
  }
  return count;
}

/**
 * Decide whether a member may reserve a given tool.
 * @param toolId - the requested tool identifier.
 * @param memberId - the requesting member identifier.
 * @param clock - the injected clock.
 * @returns an object describing eligibility and reason.
 */
function canMemberReserve(toolId: string, memberId: string, clock: Clock): { ok: boolean; reason: string } {
  const tool = findTool(toolId);
  if (tool === undefined) {
    return { ok: false, reason: 'Unknown tool.' };
  }
  if (!tool.active) {
    return { ok: false, reason: 'Tool is inactive.' };
  }
  const member = findMember(memberId);
  if (member === undefined) {
    return { ok: false, reason: 'Unknown member.' };
  }
  if (member.standing === 'Restricted') {
    return { ok: false, reason: 'Member standing is Restricted.' };
  }
  if (countMemberOverdue(memberId, clock) > 0) {
    return { ok: false, reason: 'Member has overdue loans.' };
  }
  if (isToolOnLoan(toolId)) {
    return { ok: false, reason: 'Tool is already out.' };
  }
  return { ok: true, reason: 'ok' };
}

/**
 * List catalogue rows matching the query, joined with active loans.
 * @param query - the catalogue query.
 * @param clock - the injected clock.
 * @returns the matching CatalogueRow entries.
 */
// req-1
// req-2
// req-11
function listTools(query: CatalogueQuery, clock: Clock): CatalogueRow[] {
  const tools = searchCatalogue(query);
  const rows: CatalogueRow[] = [];
  for (let i = 0; i < tools.length; i += 1) {
    const tool = tools[i];
    let dueBackAt: string | null = null;
    for (let j = 0; j < store.loans.length; j += 1) {
      const loan = store.loans[j];
      if (
        loan.toolId === tool.id &&
        loan.status !== 'Returned' &&
        loan.dueAt !== null &&
        dueBackAt === null
      ) {
        dueBackAt = loan.dueAt;
      }
    }
    rows.push({
      id: tool.id,
      name: tool.name,
      category: tool.category,
      condition: tool.condition,
      loanLengthDays: tool.loanLengthDays,
      active: tool.active,
      replacementCostPence: tool.replacementCostPence,
      dueBackAt: dueBackAt,
    });
  }
  return rows;
}

/**
 * Filter the persisted tool collection by search text, category and availability.
 * @param query - the catalogue query.
 * @returns the matching Tool entries.
 */
// req-2
function searchCatalogue(query: CatalogueQuery): Tool[] {
  const text = query.searchText !== undefined ? query.searchText.trim().toLowerCase() : '';
  const results: Tool[] = [];
  for (let i = 0; i < store.tools.length; i += 1) {
    const tool = store.tools[i];
    if (text.length > 0) {
      const haystack = (tool.name + ' ' + tool.category).toLowerCase();
      if (haystack.indexOf(text) === -1) {
        continue;
      }
    }
    if (query.category !== undefined && query.category.length > 0 && tool.category !== query.category) {
      continue;
    }
    if (query.availability !== undefined) {
      const onLoan = isToolOnLoan(tool.id);
      if (query.availability === 'available' && onLoan) {
        continue;
      }
      if (query.availability === 'on-loan' && !onLoan) {
        continue;
      }
    }
    results.push(tool);
  }
  return results;
}

/**
 * Reserve a tool for a member, refusing when ineligible or unavailable.
 * @param toolId - the requested tool identifier.
 * @param memberId - the requesting member identifier.
 * @param clock - the injected clock.
 * @returns the created Loan, or a marker record when refused.
 */
// req-3
// req-7
async function reserveTool(toolId: string, memberId: string, clock: Clock): Promise<Loan> {
  const eligibility = canMemberReserve(toolId, memberId, clock);
  if (!eligibility.ok) {
    return { id: '', toolId: toolId, memberId: memberId, status: 'Returned', checkedOutAt: null, dueAt: null, returnedAt: null };
  }
  const tool = findTool(toolId);
  const loanLength = tool !== undefined ? tool.loanLengthDays : 0;
  const loan: Loan = {
    id: buildId('loan', toolId + memberId + clock.now()),
    toolId: toolId,
    memberId: memberId,
    status: 'Reserved',
    checkedOutAt: null,
    dueAt: computeDueAt(clock.now(), loanLength),
    returnedAt: null,
  };
  store.loans.push(loan);
  return loan;
}

/**
 * Check a tool out to a member, creating an Out loan or transitioning a Reserved one.
 * @param toolId - the requested tool identifier.
 * @param memberId - the requesting member identifier.
 * @param clock - the injected clock.
 * @returns the resulting Loan.
 */
// req-4
async function checkOutTool(toolId: string, memberId: string, clock: Clock): Promise<Loan> {
  const tool = findTool(toolId);
  if (tool === undefined || !tool.active) {
    return { id: '', toolId: toolId, memberId: memberId, status: 'Returned', checkedOutAt: null, dueAt: null, returnedAt: null };
  }
  for (let i = 0; i < store.loans.length; i += 1) {
    const loan = store.loans[i];
    if (loan.toolId === toolId && loan.status !== 'Returned') {
      loan.status = 'Out';
      loan.checkedOutAt = clock.now();
      if (loan.dueAt === null) {
        loan.dueAt = computeDueAt(clock.now(), tool.loanLengthDays);
      }
      return loan;
    }
  }
  const created: Loan = {
    id: buildId('loan', toolId + memberId + clock.now()),
    toolId: toolId,
    memberId: memberId,
    status: 'Out',
    checkedOutAt: clock.now(),
    dueAt: computeDueAt(clock.now(), tool.loanLengthDays),
    returnedAt: null,
  };
  store.loans.push(created);
  return created;
}

/**
 * Record a return, setting returned-at and moving status to Returned.
 * @param loanId - the loan identifier.
 * @param clock - the injected clock.
 * @returns the updated Loan, or a marker record when refused.
 */
// req-5
async function checkInTool(loanId: string, clock: Clock): Promise<Loan> {
  const loan = findLoan(loanId);
  if (loan === undefined) {
    return { id: '', toolId: '', memberId: '', status: 'Returned', checkedOutAt: null, dueAt: null, returnedAt: null };
  }
  if (loan.status === 'Returned') {
    return { id: '', toolId: loan.toolId, memberId: loan.memberId, status: 'Returned', checkedOutAt: null, dueAt: null, returnedAt: null };
  }
  loan.returnedAt = clock.now();
  loan.status = 'Returned';
  return loan;
}

/**
 * Validate and persist a damage report against a loan.
 * @param loanId - the loan identifier.
 * @param note - the free-text damage note.
 * @param replacementChargePence - the non-negative estimate in pence.
 * @param clock - the injected clock.
 * @returns the created DamageReport, or a marker record when refused.
 */
// req-8
async function reportDamage(loanId: string, note: string, replacementChargePence: number, clock: Clock): Promise<DamageReport> {
  const trimmed = note !== undefined && note !== null ? note.trim() : '';
  if (trimmed.length === 0) {
    return { id: '', loanId: loanId, note: '', replacementChargePence: 0, recordedAt: '' };
  }
  if (!Number.isInteger(replacementChargePence) || replacementChargePence < 0) {
    return { id: '', loanId: loanId, note: '', replacementChargePence: 0, recordedAt: '' };
  }
  const loan = findLoan(loanId);
  if (loan === undefined) {
    return { id: '', loanId: loanId, note: '', replacementChargePence: 0, recordedAt: '' };
  }
  const report: DamageReport = {
    id: buildId('damage', loanId + trimmed),
    loanId: loanId,
    note: trimmed,
    replacementChargePence: replacementChargePence,
    recordedAt: clock.now(),
  };
  store.damageReports.push(report);
  return report;
}

/**
 * Annotate loans past their due date using the injected clock.
 * @param loans - the loans to inspect.
 * @param clock - the injected clock.
 * @returns the loans with derived Overdue status where applicable.
 */
// req-6
// req-10
function markOverdue(loans: Loan[], clock: Clock): Loan[] {
  const now = parseTime(clock.now());
  const result: Loan[] = [];
  for (let i = 0; i < loans.length; i += 1) {
    const loan = loans[i];
    const derived = deriveLoanStatus(loan, clock);
    const copy: Loan = {
      id: loan.id,
      toolId: loan.toolId,
      memberId: loan.memberId,
      status: derived,
      checkedOutAt: loan.checkedOutAt,
      dueAt: loan.dueAt,
      returnedAt: loan.returnedAt,
    };
    if (loan.status !== 'Returned' && loan.dueAt !== null && parseTime(loan.dueAt) < now) {
      copy.status = 'Overdue';
    }
    result.push(copy);
  }
  return result;
}

/**
 * List all overdue loans sorted by lateness, most late first.
 * @param clock - the injected clock.
 * @returns the OverdueRow entries for the dashboard.
 */
// req-6
function getOverdueLoans(clock: Clock): OverdueRow[] {
  const now = parseTime(clock.now());
  const rows: OverdueRow[] = [];
  for (let i = 0; i < store.loans.length; i += 1) {
    const loan = store.loans[i];
    if (
      loan.status !== 'Returned' &&
      loan.dueAt !== null &&
      parseTime(loan.dueAt) < now
    ) {
      rows.push({
        loanId: loan.id,
        toolId: loan.toolId,
        memberId: loan.memberId,
        dueAt: loan.dueAt,
        daysLate: Math.floor((now - parseTime(loan.dueAt)) / 86400000),
      });
    }
  }
  rows.sort((a: OverdueRow, b: OverdueRow): number => b.daysLate - a.daysLate);
  return rows;
}
export { listTools, searchCatalogue, reserveTool, checkOutTool, checkInTool, reportDamage, markOverdue, getOverdueLoans };

